<script setup lang="ts">
import {computed,onBeforeUnmount,onMounted,shallowRef} from 'vue';
import type {DeliveryAsset,ModelDeliveryContext} from '../types/model-delivery';
import ReadOnlyFacts from '../components/ReadOnlyFacts.vue';
const props=defineProps<{context:ModelDeliveryContext}>(),s=shallowRef(props.context.snapshot());
let alive=true,stop:(()=>void)|undefined;
const busy=computed(()=>Boolean(s.value.busy)||props.context.signal.aborted);
const canPublish=computed(()=>s.value.canPublish===true&&!busy.value&&!s.value.uncertain&&!s.value.awaitingReadback);
const partial=computed(()=>s.value.weightStatus?.toUpperCase()==='PARTIAL'||s.value.versionStatus?.toUpperCase()==='PARTIAL');
const mode=computed(()=>s.value.mode?({local:'本地管理',external:'外部交付'}[s.value.mode.toLowerCase()]||s.value.mode):'原交付模式未提供');
const tagText=(value:string[]|null|undefined)=>!Array.isArray(value)?'未记录':value.length?value.join('、'):'已记录空类别集合';
const fields=(row:DeliveryAsset):[string,unknown][]=>[['Artifact ID',row.artifactId],['Weight ID',row.weightId],['同步状态',row.status],['OSS 上传状态',row.storageStatus],['远端身份验证',row.identityStatus],['算力分类 ID',row.computePlatformId],['芯片',row.chipCode],['SHA256',row.sha256],['大小（字节）',row.sizeBytes]];
function dispose(){stop?.();stop=undefined;props.context.signal.removeEventListener('abort',dispose)}
onMounted(()=>{if(props.context.signal.aborted)return;stop=props.context.subscribe(value=>{if(alive&&!props.context.signal.aborted)s.value=value});props.context.signal.addEventListener('abort',dispose,{once:true})});
onBeforeUnmount(()=>{alive=false;dispose()});
</script>
<template><section class="model-delivery" aria-label="模型交付工作台" :aria-busy="Boolean(s.busy)">
 <header class="delivery-header"><div><small>模型管理 / 单版本交付</small><h2>{{ s.algorithmName||s.algorithmId }}</h2><p>{{ s.versionName||s.versionId }} · 项目 {{ s.projectId }}</p></div><div class="header-actions"><el-button :disabled="busy" @click="context.actions.legacy()">使用原交付界面</el-button><el-button :disabled="context.signal.aborted" @click="context.actions.close()">关闭</el-button></div></header>
 <div class="delivery-overview"><section><span>当前模式</span><strong>{{ mode }}</strong></section><section><span>Version 登记</span><strong>{{ s.versionStatus||'未提供' }}</strong></section><section><span>Weight 交付</span><strong>{{ s.weightStatus||'未提供' }}</strong></section><section><span>当前交付资产</span><strong>{{ s.currentTotal??s.current.length }}</strong></section></div>
 <div v-if="s.uncertain" class="delivery-notice warning" role="alert"><strong>UNKNOWN · 发布结果尚未确认</strong><p>先查询原发布状态并核对 Version、Weight 身份；当前禁止重复提交。</p></div>
 <div v-else-if="s.awaitingReadback" class="delivery-notice warning" role="status"><strong>等待发布状态读回</strong><p>请求已返回，最终权重结果尚待原 Owner 核实；当前禁止重复提交。</p></div>
 <div v-if="s.error" class="delivery-notice error" role="alert">{{ s.error }}</div>
 <div v-if="partial" class="delivery-notice warning" role="status"><strong>PARTIAL · 部分交付</strong><p>Version 登记与各 Weight 状态分别核验；保留原已完成事实和待处理项。</p></div>
 <div class="delivery-admission" aria-label="原发布准入"><strong>{{ s.preflight?.ready===true?'原发布预检通过':s.preflight?.ready===false?'原发布预检尚未通过':'正在读取发布准入事实' }}</strong><p v-if="s.preflight?.message">{{ s.preflight.message }}</p><p v-if="s.message" role="status">{{ s.message }}</p><div class="header-actions"><el-button v-if="context.actions.configure" :disabled="busy" @click="context.actions.configure()">平台对接配置</el-button><el-button v-if="context.actions.storage" :disabled="busy" @click="context.actions.storage()">模型产物存储配置</el-button></div></div>
 <main class="delivery-assets" aria-label="当前版本模型资产"><div class="section-heading"><h3>本次交付资产</h3><span>项目 / 算法 / 版本身份由原 Owner 核验</span></div><p v-if="!s.current.length">{{ s.busy?'正在读取当前资产与交付状态…':'当前未提供可交付资产；不能据此认定上传或发布完成。' }}</p>
  <article v-for="(row,index) in s.current" :key="row.artifactId||`${row.weightId}:${index}`" class="delivery-asset"><header><div><h4>{{ row.fileName||row.artifactId||'名称未提供' }}</h4><p>{{ row.target||'目标未提供' }} · {{ row.role||'交付角色未提供' }}</p></div><el-tag type="info" effect="plain">{{ row.status||'状态未提供' }}</el-tag></header><p v-if="row.reviewRequired" class="asset-review" role="status">此权重需人工核对身份，不能把远端已登记视为已读回确认。</p><ReadOnlyFacts :fields="fields(row)"/><p v-if="row.note">{{ row.note }}</p><p v-if="row.lastError" class="asset-error">{{ row.lastError }}</p>
   <details class="delivery-evidence"><summary>模型元数据与类别提交证据</summary><ReadOnlyFacts :fields="[['元数据同步',row.metadataStatus],['输入宽度',row.metadata?.width],['输入高度',row.metadata?.height],['模型版本',row.metadata?.yoloVersion],['记录类别',tagText(row.metadata?.tags)],['冻结类别',tagText(row.frozenTags)],['本地类别',tagText(row.localTags)],['准备提交类别',tagText(row.preparedTags)],['HTTP 请求记录类别',tagText(row.requestTags)],['已确认提交类别',tagText(row.confirmedTags)],['远端读回状态',row.remoteTagsStatus],['远端类别',tagText(row.remoteTags)]]"/><p>请求记录、提交回执、远端读回是不同证据；远端未返回类别不表示已验证。</p></details>
  </article><p v-if="s.truncated" class="delivery-footnote">当前为有界资产摘要；完整清单及诊断请使用原交付界面。</p>
 </main>
 <details v-if="s.historical.length" class="delivery-history"><summary>历史成果 {{ s.historicalTotal??s.historical.length }} 份（不参与本次交付）</summary><article v-for="(row,index) in s.historical" :key="row.artifactId||index"><h4>{{ row.fileName||row.artifactId||'历史成果' }}</h4><ReadOnlyFacts :fields="fields(row)"/></article></details>
 <footer class="delivery-footer"><p>OSS 上传、Version 登记、Weight 同步及目标硬件验证分别记录。查询状态不会发布；只有明确确认才由原 Owner 提交。</p><div class="header-actions"><el-button :disabled="busy" :loading="s.busy==='checking'" @click="context.actions.refresh()">查询发布状态</el-button><el-button :disabled="context.signal.aborted" @click="context.actions.close()">返回</el-button><el-button type="primary" :disabled="!canPublish" :loading="s.busy==='publishing'" @click="context.actions.publish()">确认同步到新畅联</el-button></div></footer>
</section></template>
<style scoped>
.model-delivery{display:flex;flex-direction:column;min-width:0;background:var(--el-bg-color,#fff);color:var(--el-text-color-primary,#303133)}.delivery-header{display:flex;align-items:center;justify-content:space-between;gap:16px;padding:18px 20px;border-bottom:1px solid var(--el-border-color-lighter,#ebeef5)}.delivery-header h2{font-size:20px;margin:5px 0}.delivery-header p,.delivery-header small{margin:0;font-size:12px;line-height:1.6;color:var(--el-text-color-secondary,#777);overflow-wrap:anywhere}.header-actions{display:flex;gap:8px;flex-wrap:wrap;align-items:center}.header-actions :deep(.el-button){margin:0}.delivery-overview{display:grid;grid-template-columns:repeat(4,minmax(0,1fr));gap:12px;padding:16px 20px;background:var(--el-fill-color-lighter,#fafafa)}.delivery-overview section{border:1px solid var(--el-border-color-lighter,#ebeef5);padding:12px;background:var(--el-bg-color,#fff);border-radius:8px;min-width:0}.delivery-overview span{display:block;font-size:12px;color:var(--el-text-color-secondary,#777)}.delivery-overview strong{display:block;margin-top:7px;font-size:16px;overflow-wrap:anywhere}.delivery-notice{padding:12px 20px;font-size:13px;line-height:1.6;overflow-wrap:anywhere}.delivery-notice p{margin:4px 0 0}.warning{background:var(--el-color-warning-light-9,#fdf6ec)}.error{background:var(--el-color-danger-light-9,#fef0f0);color:var(--el-color-danger,#f56c6c)}.delivery-admission{padding:14px 20px;border-bottom:1px solid var(--el-border-color-lighter,#ebeef5);font-size:13px;line-height:1.6}.delivery-admission p{margin:5px 0 10px}.delivery-assets{padding:16px 20px;min-width:0}.section-heading{display:flex;justify-content:space-between;gap:12px;align-items:baseline;margin-bottom:14px}.section-heading h3{font-size:16px;margin:0}.section-heading span{font-size:12px;color:var(--el-text-color-secondary,#777)}.delivery-asset{border:1px solid var(--el-border-color-lighter,#ebeef5);border-radius:8px;padding:16px;margin-bottom:14px;overflow-wrap:anywhere}.delivery-asset>header{display:flex;justify-content:space-between;gap:12px;align-items:flex-start;margin-bottom:14px}.delivery-asset h4{font-size:14px;margin:0 0 6px}.delivery-asset header p{font-size:12px;color:var(--el-text-color-secondary,#777);margin:0}.delivery-asset :deep(.readonly-facts){font-size:13px;grid-template-columns:minmax(120px,.7fr) minmax(0,1.3fr)}.delivery-asset :deep(dd){overflow-wrap:anywhere}.asset-review{padding:9px;background:var(--el-color-warning-light-9,#fdf6ec);font-size:12px}.asset-error{color:var(--el-color-danger,#f56c6c);font-size:13px}.delivery-evidence{border-top:1px solid var(--el-border-color-lighter,#ebeef5);padding-top:12px;margin-top:12px;font-size:12px}.delivery-evidence summary{cursor:pointer;font-weight:600;margin-bottom:10px}.delivery-evidence p,.delivery-footnote{color:var(--el-text-color-secondary,#777);font-size:12px;line-height:1.6}.delivery-history{margin:0 20px 18px;padding:12px;border:1px solid var(--el-border-color-lighter,#ebeef5);border-radius:8px;font-size:13px}.delivery-history summary{cursor:pointer}.delivery-history article{border-top:1px solid var(--el-border-color-lighter,#ebeef5);padding-top:8px;margin-top:12px;overflow-wrap:anywhere}.delivery-footer{border-top:1px solid var(--el-border-color-lighter,#ebeef5);padding:14px 20px;display:flex;align-items:center;justify-content:space-between;gap:16px;flex-wrap:wrap}.delivery-footer>p{font-size:12px;line-height:1.6;color:var(--el-text-color-secondary,#777);flex:1;min-width:230px;margin:0}
@media(max-width:900px){.delivery-overview{grid-template-columns:repeat(2,minmax(0,1fr))}.delivery-header{align-items:flex-start;flex-wrap:wrap}.delivery-footer .header-actions{width:100%;justify-content:flex-end}}@media(max-width:600px){.delivery-header,.delivery-assets,.delivery-admission,.delivery-notice,.delivery-footer{padding:12px}.delivery-overview{padding:12px;gap:8px}.delivery-overview strong{font-size:14px}.section-heading{flex-direction:column;gap:5px}.delivery-asset{padding:12px}.delivery-asset :deep(.readonly-facts){grid-template-columns:minmax(100px,.8fr) minmax(0,1.2fr);font-size:12px}.delivery-history{margin:0 12px 12px}}
</style>
